    private void loginButtonActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_loginButtonActionPerformed
        String userName = jTextField1.getText();
        String password = jPasswordField1.getText();
        try {
            Connection connection = (Connection) DriverManager.getConnection("jdbc:mysql://localhost:3306/credentials", "root", "tahsin");

            PreparedStatement st = (PreparedStatement) connection.prepareStatement("Select username, password from adminlogin where binary username=? and binary password=?");
            PreparedStatement st1 = (PreparedStatement) connection.prepareStatement("Select username, password from customerlogin where binary username=? and binary password=?");

            st.setString(1, userName);
            st.setString(2, password);
            st1.setString(1, userName);
            st1.setString(2, password);
            ResultSet rs = st.executeQuery();
            ResultSet rs1 = st1.executeQuery();
            if (rs.next()) {
                dispose();
                AdminDashboard di = new AdminDashboard();
                di.usernameField.setText(jTextField1.getText());
                di.setVisible(true);
                rightDialog.setVisible(true);
            } else if (rs1.next()) {
                dispose();
                CustomerDashboard cdi = new CustomerDashboard();
                cdi.usernameField.setText(jTextField1.getText());
                cdi.setVisible(true);
                rightDialog.setVisible(true);
            } else {
                wrongDialog.setVisible(true);
            }
        } catch (SQLException sqlException) {
            sqlException.printStackTrace();
        }
    }//GEN-LAST:event_loginButtonActionPerformed

