    private void jButton9ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton9ActionPerformed
        String seqQ = jTextField15.getText();
        String username = jTextField13.getText();
        String password = jPasswordField3.getText();
        try {
            Connection connection = (Connection) DriverManager.getConnection("jdbc:mysql://localhost:3306/credentials", "root", "tahsin");

            PreparedStatement st = (PreparedStatement) connection.prepareStatement("select username, securityQuestion from customerlogin where username=? and securityQuestion=?");

            st.setString(1, username);
            st.setString(2, seqQ);
            ResultSet rs = st.executeQuery();

            if (seqQ.isEmpty() || username.isEmpty() || password.isEmpty()) {
                jLabel9.setText("");
                registerWrongDialog.setVisible(true);
            } else if (rs.next()) {
                PreparedStatement st1 = (PreparedStatement) connection.prepareStatement("UPDATE customerlogin SET password = ? WHERE username = ?");
                st1.setString(1, password);
                st1.setString(2, username);

                int rowsUpdated = st1.executeUpdate();

                if (rowsUpdated > 0) {
                    jLabel9.setText("");
                    forgotDialog.dispose();
                    recoverPassDialog.setVisible(true);
                }
            } else {
                jLabel9.setText("Username or Security Question doesn't match");
            }

            rs.close();
            st.close();
            connection.close();
        } catch (SQLException sqlException) {
            sqlException.printStackTrace();
        }

    }//GEN-LAST:event_jButton9ActionPerformed

